   */
  public static getInstance(): NetworkClient {
    if (!NetworkClient.instance) {
      NetworkClient.instance = new NetworkClient();
    }
    return NetworkClient.instance;
  }

  /**
   * 获取 Axios 实例
   */
  public getAxios(): AxiosInstance {
    return this.axiosInstance;
  }

