   * @param {number} goodsId 商品ID
   * @returns {Promise<Cart | undefined>} 匹配到的购物车商品
   */
  getCartByGoodsId(goodsId: number): Promise<Cart | undefined> {
    return this.dataSource.getCartByGoodsId(goodsId);
  }
}
