   */
  readonly isSelectMode: boolean = this.routeParam.isSelectMode ?? false;
  /**
   * 是否显示删除确认弹窗
   */
  @Trace
  isDeleteDialogVisible: boolean = false;
  /**
   * 当前待删除的地址 ID
   */
  @Trace
  deleteId: number | null = null;

  /**
   * 请求地址分页数据
   * @returns {Promise<NetworkResponse<NetworkPageData<Address>>>} 网络请求 Promise
   */
